import { useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Typography,
} from "@mui/material";

export default function FeedbackForm({ open, onClose }) {
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Save feedback to localStorage
    const feedbacks = JSON.parse(localStorage.getItem("feedbacks") || "[]");
    feedbacks.push({ ...form, date: new Date().toISOString() });
    localStorage.setItem("feedbacks", JSON.stringify(feedbacks));
    setSubmitted(true);
  };

  const handleClose = () => {
    setForm({ name: "", email: "", message: "" });
    setSubmitted(false);
    onClose();
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>User Feedback</DialogTitle>
      <DialogContent>
        {submitted ? (
          <Typography sx={{ mt: 2 }}>Thank you for your feedback!</Typography>
        ) : (
          <form onSubmit={handleSubmit}>
            <TextField
              margin="normal"
              label="Name"
              name="name"
              fullWidth
              value={form.name}
              onChange={handleChange}
            />
            <TextField
              margin="normal"
              label="Email"
              name="email"
              type="email"
              fullWidth
              value={form.email}
              onChange={handleChange}
            />
            <TextField
              margin="normal"
              label="Your Feedback"
              name="message"
              fullWidth
              multiline
              minRows={3}
              value={form.message}
              onChange={handleChange}
              required
            />
            <DialogActions>
              <Button onClick={handleClose}>Cancel</Button>
              <Button type="submit" variant="contained">
                Submit
              </Button>
            </DialogActions>
          </form>
        )}
      </DialogContent>
      {submitted && (
        <DialogActions>
          <Button onClick={handleClose} variant="contained">
            Close
          </Button>
        </DialogActions>
      )}
    </Dialog>
  );
}
